func TestViewerCanReorderPlaylistWithoutDragging(t *testing.T) {
	t.Parallel()
	media, data := t.TempDir(), t.TempDir()
	for _, title := range []string{"Alpha", "Beta", "Gamma"} {
		if err := os.WriteFile(filepath.Join(media, title+".mp4"), []byte("video"), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	handler := server.New(server.Config{MediaDir: media, DataDir: data})
	postForm(t, handler, "/playlists", "name=Queue")
	library := apiCall(t, handler, "", http.MethodGet, "/api/v1/library?view=movies", nil)
	var catalog struct {
		Items []struct{ ID, Title string } `json:"items"`
	}
	if err := json.Unmarshal(library.Body.Bytes(), &catalog); err != nil {
		t.Fatal(err)
	}
	for _, item := range catalog.Items {
		collectionForm(t, handler, "/playlist/Queue/items/"+item.ID, "included=true")
	}
	page := httptest.NewRecorder()
	handler.ServeHTTP(page, httptest.NewRequestWithContext(t.Context(), http.MethodGet, "/playlist/Queue", nil))
	mustContainAll(t, page.Body.String(), `aria-label="Move Alpha later"`, `aria-label="Move Beta earlier"`, `class="playlist-order"`)

	moved := collectionForm(t, handler, "/playlist/Queue/order", "id="+catalog.Items[1].ID+"&direction=up")
	if moved.Code != http.StatusSeeOther {
		t.Fatalf("move = %d %q", moved.Code, moved.Body.String())
	}
	ordered := apiCall(t, handler, "", http.MethodGet, "/api/v1/playlists/Queue", nil)
	if strings.Index(ordered.Body.String(), `"title":"Beta"`) > strings.Index(ordered.Body.String(), `"title":"Alpha"`) {
		t.Fatalf("playlist order = %q", ordered.Body.String())
	}
	for _, body := range []string{"", "id=" + catalog.Items[1].ID, "id=" + catalog.Items[1].ID + "&direction=sideways", "id=" + catalog.Items[1].ID + "&direction=up&direction=down", "id=" + catalog.Items[1].ID + "&direction=up&unknown=x", "id=" + strings.Repeat("a", 65) + "&direction=up"} {
		invalid := collectionForm(t, handler, "/playlist/Queue/order", body)
		if invalid.Code != http.StatusBadRequest {
			t.Fatalf("invalid move %q = %d %q", body, invalid.Code, invalid.Body.String())
		}
	}
	unchanged := apiCall(t, handler, "", http.MethodGet, "/api/v1/playlists/Queue", nil)
	if strings.Index(unchanged.Body.String(), `"title":"Beta"`) > strings.Index(unchanged.Body.String(), `"title":"Alpha"`) {
		t.Fatalf("invalid moves changed playlist = %q", unchanged.Body.String())
	}
}

func TestViewerCanDismissContinueWatchingWithoutDeletingHistory(t *testing.T) {
	t.Parallel()

	handler, token := apiServer(t)
	libraryResponse := apiCall(t, handler, token, http.MethodGet, "/api/v1/library", nil)
	var catalog struct {
		Items []struct {
			ID string `json:"id"`
		} `json:"items"`
	}
	if err := json.Unmarshal(libraryResponse.Body.Bytes(), &catalog); err != nil || len(catalog.Items) == 0 {
		t.Fatalf("library = %d %q: %v", libraryResponse.Code, libraryResponse.Body.String(), err)
	}
	id := catalog.Items[0].ID
	assertAPICalls(t, handler, token, []apiTestCall{{Method: http.MethodPut, Path: "/api/v1/items/" + id + "/progress", Body: map[string]any{"seconds": 61}, Status: http.StatusOK}})
	home := apiCall(t, handler, token, http.MethodGet, "/", nil)
	assertAPIBody(t, home, http.StatusOK, `action="/continue-watching/`+id+`/remove"`, "Remove Arrival from Continue Watching")
	spanishHome := apiCall(t, handler, token, http.MethodGet, "/?lang=es", nil)
	assertAPIBody(t, spanishHome, http.StatusOK, "Eliminar Arrival de Seguir viendo")
	assertAPICalls(t, handler, token, []apiTestCall{{Method: http.MethodDelete, Path: "/api/v1/items/" + id + "/continue-watching", Body: nil, Status: http.StatusNoContent}})
	assertAPICalls(t, handler, token, []apiTestCall{{Method: http.MethodPut, Path: "/api/v1/items/" + id + "/progress", Body: map[string]any{"seconds": 61}, Status: http.StatusOK}})
	removed := apiCall(t, handler, token, http.MethodPost, "/continue-watching/"+id+"/remove", nil)
	if removed.Code != http.StatusSeeOther {
		t.Fatalf("web dismiss = %d %q", removed.Code, removed.Body.String())
	}

	history := apiCall(t, handler, token, http.MethodGet, "/api/v1/history", nil)
	assertAPIBody(t, history, http.StatusOK, "Arrival", `"seconds":61`)
	home = apiCall(t, handler, token, http.MethodGet, "/", nil)
	if strings.Contains(home.Body.String(), "Continue watching") {
		t.Fatalf("dismissed item remains in Continue Watching: %q", home.Body.String())
	}
	historyPage := apiCall(t, handler, token, http.MethodGet, "/?view=history", nil)
	assertAPIBody(t, historyPage, http.StatusOK, "Playback history", "Arrival")
}

func TestRejectedProgressCannotEmitPlaybackAudit(t *testing.T) {
	store := newProgressStore("")
	audit := newAuditStore(t.Context(), "", nil)
	store.SetAuditor(audit)
	request := httptest.NewRequestWithContext(withViewer(t.Context(), viewerProfile{ID: "viewer"}), http.MethodPut, "/", nil)
	accepted, err := store.SetRevision(request, "item", 120, nil, "phone", 2)
	if err != nil || !accepted || len(audit.Query("playback", 10)) != 1 {
		t.Fatalf("initial progress = %v %v", accepted, err)
	}
	watched := true
	accepted, err = store.SetRevision(request, "item", 10, &watched, "phone", 1)
	if err != nil || accepted || len(audit.Query("playback", 10)) != 1 || store.Get(request, "item").Seconds != 120 {
		t.Fatalf("stale progress changed state or audit: %v %v", accepted, err)
	}
}

